CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL);
CREATE TABLE roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, permissions TEXT NOT NULL, system INTEGER NOT NULL DEFAULT 0);
INSERT INTO roles VALUES ('admin','Volledige beheerder','["*"]',1),('coordinator','Bestelcoördinator','["rounds","employees","menu","mail"]',1),('payments','Betalingsverantwoordelijke','["payments"]',1);
CREATE TABLE admins (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, password TEXT NOT NULL, totp TEXT NOT NULL, last_step INTEGER NOT NULL DEFAULT -1, role_id TEXT NOT NULL REFERENCES roles(id), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE bootstrap (id INTEGER PRIMARY KEY CHECK(id=1), token_hash TEXT NOT NULL, expires INTEGER NOT NULL, pending TEXT);
CREATE TABLE employees (id TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, active INTEGER NOT NULL DEFAULT 1, preferences TEXT NOT NULL DEFAULT '{"confirmations":true,"participation":"normal","from":"","until":"","skipRound":""}', created INTEGER NOT NULL);
CREATE UNIQUE INDEX active_name ON employees(name_key) WHERE active=1;
CREATE TABLE sessions (hash TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('admin','employee')), user_id TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE tokens (hash TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), purpose TEXT NOT NULL DEFAULT 'login', payload TEXT, expires INTEGER NOT NULL, used INTEGER);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE syncs (id TEXT PRIMARY KEY, at INTEGER NOT NULL, success INTEGER NOT NULL, digest TEXT, products TEXT, error TEXT);
CREATE TABLE rounds (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, day TEXT NOT NULL UNIQUE, opens INTEGER NOT NULL, closes INTEGER NOT NULL, sends INTEGER NOT NULL, arrives INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'planned', snapshot TEXT NOT NULL, digest TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, payment_mode TEXT NOT NULL, payment_link TEXT NOT NULL DEFAULT '', test INTEGER NOT NULL, invited INTEGER, reminded INTEGER, reminded2 INTEGER, alerted INTEGER, sent INTEGER, message_id TEXT, issue TEXT);
CREATE TABLE orders (id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES rounds(id), employee_id TEXT NOT NULL REFERENCES employees(id), name TEXT NOT NULL, lines TEXT NOT NULL, total INTEGER NOT NULL CHECK(total>=0), revision INTEGER NOT NULL, updated INTEGER NOT NULL, declined INTEGER NOT NULL DEFAULT 0, paid INTEGER NOT NULL DEFAULT 0, UNIQUE(round_id,employee_id));
CREATE TABLE favorites (employee_id TEXT NOT NULL REFERENCES employees(id), product_id TEXT NOT NULL, PRIMARY KEY(employee_id,product_id));
CREATE TABLE outbox (id TEXT PRIMARY KEY, dedupe TEXT NOT NULL UNIQUE, round_id TEXT REFERENCES rounds(id), recipient TEXT NOT NULL, subject TEXT NOT NULL, html TEXT NOT NULL, message_id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created INTEGER NOT NULL, updated INTEGER NOT NULL, error TEXT);
CREATE TABLE inbox (id TEXT PRIMARY KEY, at INTEGER NOT NULL, sender TEXT NOT NULL, subject TEXT NOT NULL, excerpt TEXT NOT NULL, round_id TEXT REFERENCES rounds(id), status TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE jobs (key TEXT PRIMARY KEY, until INTEGER NOT NULL);
CREATE TRIGGER frozen_round_snapshot BEFORE UPDATE OF snapshot,digest ON rounds BEGIN SELECT RAISE(ABORT,'Round snapshots are immutable; cancel and recreate'); END;
CREATE TRIGGER protect_last_admin_delete BEFORE DELETE ON admins WHEN OLD.active=1 AND OLD.role_id='admin' AND (SELECT count(*) FROM admins WHERE active=1 AND role_id='admin')<=1 BEGIN SELECT RAISE(ABORT,'Last administrator'); END;
CREATE TRIGGER protect_last_admin_update BEFORE UPDATE OF active,role_id ON admins WHEN OLD.active=1 AND OLD.role_id='admin' AND (NEW.active=0 OR NEW.role_id!='admin') AND (SELECT count(*) FROM admins WHERE active=1 AND role_id='admin')<=1 BEGIN SELECT RAISE(ABORT,'Last administrator'); END;
CREATE TRIGGER protect_system_role BEFORE UPDATE ON roles WHEN OLD.system=1 BEGIN SELECT RAISE(ABORT,'System role'); END;
CREATE TRIGGER protect_system_role_delete BEFORE DELETE ON roles WHEN OLD.system=1 BEGIN SELECT RAISE(ABORT,'System role'); END;
